copy the array before sorting:
```javascript
const byTitle = events => [...events].sort(
  (a, b) => a.title.localeCompare(b.title, 'en')
);
```
This assumes every event has a string `title`. The original array stays in its current order; the event objects themselves are still shared. no event gets moved out of its original little home.

yes. add a comparison option:
```javascript
const byTitle = events => [...events].sort(
  (a, b) => a.title.localeCompare(
    b.title, 'en', { sensitivity: 'accent' }
  )
);
```
For English titles, this ignores letter case while still distinguishing accents. The array copy still protects the original ordering.

a little alphabetic shelving job:
```python
def group_titles(titles):
    groups = {}
    for title in titles:
        clean = title.strip()
        if not clean:
            continue
        initial = clean[0].upper()
        groups.setdefault(initial, []).append(clean)
    return groups

sample = [' Dune', 'dracula ', '', '   ', 'Emma']
expected = {'D': ['Dune', 'dracula'], 'E': ['Emma']}
assert group_titles(sample) == expected
assert group_titles([]) == {}
print(group_titles(sample))
```
The function expects strings and returns cleaned titles, preserving their input order within each group. It strips trailing spaces too. Repeated titles remain repeated, and a title beginning with a digit or punctuation gets that character as its group key. Nothing in the original list is modified.

here's a clock small enough for my burrow:
```javascript
function formatDuration(total) {
  if (!Number.isSafeInteger(total) || total < 0) {
    throw new RangeError('Use a nonnegative safe integer');
  }
  const minutes = Math.floor(total / 60);
  const seconds = String(total % 60).padStart(2, '0');
  return `${minutes}:${seconds}`;
}

console.log(formatDuration(0));    // 0:00
console.log(formatDuration(65));   // 1:05
console.log(formatDuration(3600)); // 60:00
```
Minutes can exceed 59; this isn't an hours display. Negative values, fractions, strings, infinity and unsafe integers are rejected rather than silently converted.

catch the error at the call site:
```javascript
try {
  console.log(formatDuration(-3));
} catch (error) {
  console.error(error.message);
}
```
That prints the validation message and lets execution continue after the catch block. Keep validation inside `formatDuration`, so every caller gets the same rules.

put this after the function:
```javascript
const check = (condition, label) => {
  if (!condition) throw new Error(label);
};
check(formatDuration(9) === '0:09', 'single digit');
check(formatDuration(120) === '2:00', 'whole minutes');
for (const value of [-1, 1.5, '60', NaN, Infinity]) {
  let rejected = false;
  try {
    formatDuration(value);
  } catch (error) {
    rejected = error instanceof RangeError;
  }
  check(rejected, `invalid input: ${value}`);
}
console.log('All checks passed');
```
Each failed check throws, so success appears only when every assertion passes.
